BEGIN
 FOR p IN SELECT value FROM jsonb_array_elements(data->'records') LOOP
  SELECT pg_get_functiondef(oid),prosrc INTO STRICT d,s FROM pg_proc WHERE oid=(p->>'signature')::regprocedure;
  IF encode(digest(convert_to(replace(replace(d,'-- worker profile checksum','<worker-checksum>'),'-- worker catalog body digest','<worker-catalog>'),'UTF8'),'sha256'),'hex')<>p->>'definitionHash' OR encode(digest(convert_to(replace(replace(s,'-- worker profile checksum','<worker-checksum>'),'-- worker catalog body digest','<worker-catalog>'),'UTF8'),'sha256'),'hex')<>p->>'sourceHash'
   OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=(p->>'signature')::regprocedure AND proowner::regrole::text=p->>'owner' AND proacl::text IS NOT DISTINCT FROM p->>'acl')
  THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='higher readiness exact predecessor changed';END IF;
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(data->'regions') LOOP
  SELECT * INTO saved FROM zasp_authorization80_worker.predecessor_functions WHERE signature=r->>'signature';
  IF FOUND AND (saved.definition IS DISTINCT FROM pg_get_functiondef((r->>'signature')::regprocedure) OR saved.owner_name IS DISTINCT FROM 'zasp_discovery_authority' OR saved.acl IS DISTINCT FROM (SELECT COALESCE(proacl::text,'') FROM pg_proc WHERE oid=(r->>'signature')::regprocedure)) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='higher readiness saved root changed';END IF;
 END LOOP;
 FOR p IN SELECT value FROM jsonb_array_elements(data->'records') LOOP
  IF p->>'signature'<>'zasp_authorization80_worker.catalog_ready()' AND split_part(p->>'signature','.',1)<>'zasp_authorization80_worker' THEN
   INSERT INTO zasp_authorization80_worker.predecessor_functions SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc WHERE oid=(p->>'signature')::regprocedure ON CONFLICT(signature) DO NOTHING;
  END IF;
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(data->'regions') LOOP
  SELECT pg_get_functiondef(oid),prosrc INTO STRICT d,s FROM pg_proc WHERE oid=(r->>'signature')::regprocedure;
  IF s IS DISTINCT FROM (r->>'prefix')||(r->>'originalExpression')||(r->>'suffix') THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='higher readiness region anchor changed';END IF;
  v:=CASE WHEN r->>'prefix'='' THEN r->>'query' ELSE (r->>'prefix')||'('||(r->>'query')||')'||(r->>'suffix') END;
  IF (length(d)-length(replace(d,s,'')))/length(s)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='higher readiness definition anchor changed';END IF;
  EXECUTE replace(d,s,E'\n'||v||E'\n');
 END LOOP;
END $higher_readiness$;
