 p jsonb;e jsonb;f record;source_value text;original_value text;replacement text;computed jsonb:='{}';ctes text:='';query_value text;definition_value text;start_value integer;end_value integer;catalog_cte text;
BEGIN
 FOR p IN SELECT value FROM jsonb_array_elements(records) LOOP
  SELECT pg_get_functiondef(x.oid) definition,x.prosrc,x.proowner::regrole::text owner_name,x.proacl::text acl,l.lanname,x.provolatile,x.proisstrict,x.proparallel,x.prosecdef,x.proconfig INTO STRICT f FROM pg_proc x JOIN pg_language l ON l.oid=x.prolang WHERE x.oid=(p->>'signature')::regprocedure;
  IF f.owner_name<>'zasp_discovery_authority' OR f.acl IS DISTINCT FROM p->>'acl' OR f.lanname<>'sql' OR f.provolatile<>'s' OR f.proisstrict OR f.proparallel<>'u' OR f.prosecdef IS DISTINCT FROM(p->>'securityDefiner')::boolean OR f.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, public']
   OR length(f.prosrc)<>(p->>'sourceLength')::integer OR encode(digest(convert_to(replace(replace(f.prosrc,'-- worker profile checksum','<worker-checksum>'),'-- worker catalog body digest','<worker-catalog>'),'UTF8'),'sha256'),'hex')<>p->>'sourceHash'
   OR encode(digest(convert_to(replace(replace(f.definition,'-- worker profile checksum','<worker-checksum>'),'-- worker catalog body digest','<worker-catalog>'),'UTF8'),'sha256'),'hex')<>p->>'definitionHash'
  THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='readiness graph exact source or frame changed';END IF;
  IF p->>'signature'<>'zasp_authorization80_worker.catalog_ready()' AND split_part(p->>'signature','.',1)<>'zasp_authorization80_worker' THEN
   INSERT INTO zasp_authorization80_worker.predecessor_functions SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc WHERE oid=(p->>'signature')::regprocedure ON CONFLICT(signature) DO NOTHING;
  END IF;
  source_value:=f.prosrc;
  IF p->>'signature'='zasp_temporal77.base67_fingerprint()' THEN original_value:=source_value;END IF;
  FOR e IN SELECT value FROM jsonb_array_elements(p->'edits') LOOP
   start_value:=(e->>'start')::integer;end_value:=(e->>'end')::integer;
   IF substring(source_value FROM start_value+1 FOR end_value-start_value) IS DISTINCT FROM e->>'text' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='readiness graph call anchor changed';END IF;
   SELECT value INTO STRICT query_value FROM jsonb_each_text(computed) WHERE key=e->>'target';
   replacement:=replace(query_value,'<readiness-argument>',e->>'args');
   source_value:=substring(source_value FROM 1 FOR start_value)||replacement||substring(source_value FROM end_value+1);
  END LOOP;
  source_value:=regexp_replace(btrim(source_value),';[[:space:]]*$','');
  IF p->'parameter'<>'null'::jsonb THEN
   computed:=computed||jsonb_build_object(p->>'signature','('||source_value||' FROM (SELECT (<readiness-argument>)::'||(p#>>'{parameter,type}')||' AS '||quote_ident(p#>>'{parameter,name}')||') AS readiness_argument)');
  ELSIF p->>'signature'<>'zasp_temporal77.base67_fingerprint()' THEN
