   computed:=computed||jsonb_build_object(p->>'signature','(SELECT value FROM '||quote_ident(p->>'cte')||')');
  ELSE
   catalog_cte:='readiness_0(value) AS MATERIALIZED (SELECT zasp_authorization80_worker.catalog_ready())';
   IF left(ctes,length(catalog_cte)+1)<>catalog_cte||',' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='readiness graph materialized gate changed';END IF;
   query_value:='SELECT CASE WHEN current_user=''zasp_discovery_authority'' THEN (WITH '||catalog_cte||' SELECT CASE WHEN (SELECT value FROM readiness_0) THEN (WITH '||substring(ctes FROM length(catalog_cte)+2)||' SELECT ('||source_value||')) ELSE ('||regexp_replace(btrim(original_value),';[[:space:]]*$','')||') END) ELSE ('||regexp_replace(btrim(original_value),';[[:space:]]*$','')||') END';
  END IF;
 END LOOP;
 definition_value:=pg_get_functiondef('zasp_temporal77.base67_fingerprint()'::regprocedure);
 IF (length(definition_value)-length(replace(definition_value,original_value,'')))/length(original_value)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='readiness graph root body anchor changed';END IF;
 EXECUTE replace(definition_value,original_value,E'\n'||query_value||E'\n');
END $readiness_graph$;
